// ---------------------------------------------------------------- SHA-256 of 16 bytes (BIP39 checksum)
HD uint32_t rotr32(uint32_t x, int n) { return (x >> n) | (x << (32 - n)); }
HD uint8_t sha256_first_byte_16(const uint32_t in[4]) {
  const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,
    0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,
    0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,
    0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};
  uint32_t w[64];
  w[0] = in[0]; w[1] = in[1]; w[2] = in[2]; w[3] = in[3]; w[4] = 0x80000000u;
  for (int i = 5; i < 15; i++) w[i] = 0;
  w[15] = 128;
  for (int i = 16; i < 64; i++) {
    uint32_t s0 = rotr32(w[i - 15], 7) ^ rotr32(w[i - 15], 18) ^ (w[i - 15] >> 3);
    uint32_t s1 = rotr32(w[i - 2], 17) ^ rotr32(w[i - 2], 19) ^ (w[i - 2] >> 10);
    w[i] = w[i - 16] + s0 + w[i - 7] + s1;
  }
  uint32_t a = 0x6a09e667, b = 0xbb67ae85, c = 0x3c6ef372, d = 0xa54ff53a, e = 0x510e527f, f = 0x9b05688c, g = 0x1f83d9ab, h = 0x5be0cd19;
  for (int i = 0; i < 64; i++) {
    uint32_t S1 = rotr32(e, 6) ^ rotr32(e, 11) ^ rotr32(e, 25);
    uint32_t t1 = h + S1 + ((e & f) ^ (~e & g)) + K[i] + w[i];
    uint32_t S0 = rotr32(a, 2) ^ rotr32(a, 13) ^ rotr32(a, 22);
    uint32_t t2 = S0 + ((a & b) ^ (a & c) ^ (b & c));
    h = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
  }
  return (uint8_t)((0x6a09e667u + a) >> 24);
}

// ---------------------------------------------------------------- HMAC-SHA512 helpers
struct HmacKey { uint64_t ih[8], oh[8]; };

HD void hmac_init(HmacKey &k, const uint64_t key[16]) {  // key: zero-padded 128-byte block
  uint64_t b[16];
  for (int i = 0; i < 16; i++) b[i] = key[i] ^ 0x3636363636363636ULL;
  sha512_iv(k.ih); sha512_compress(k.ih, b);
  for (int i = 0; i < 16; i++) b[i] = key[i] ^ 0x5c5c5c5c5c5c5c5cULL;
  sha512_iv(k.oh); sha512_compress(k.oh, b);
}
// finish an HMAC: inner state after the message -> out = H(opad || inner)
HD void hmac_outer(const HmacKey &k, const uint64_t inner[8], uint64_t out[8]) {
  uint64_t b[16];
  for (int i = 0; i < 8; i++) { b[i] = inner[i]; out[i] = k.oh[i]; }
  b[8] = 0x8000000000000000ULL;
  for (int i = 9; i < 15; i++) b[i] = 0;
  b[15] = (128 + 64) * 8;
  sha512_compress(out, b);
}
// HMAC of one already padded message block (message <= 111 bytes)
HD void hmac_block(const HmacKey &k, const uint64_t blk[16], uint64_t out[8]) {
  uint64_t s[8];
  for (int i = 0; i < 8; i++) s[i] = k.ih[i];
  sha512_compress(s, blk);
  hmac_outer(k, s, out);
}
// HMAC of a 64-byte message
HD void hmac64(const HmacKey &k, const uint64_t msg[8], uint64_t out[8]) {
  uint64_t b[16];
  for (int i = 0; i < 8; i++) b[i] = msg[i];
  b[8] = 0x8000000000000000ULL;
  for (int i = 9; i < 15; i++) b[i] = 0;
  b[15] = (128 + 64) * 8;
  hmac_block(k, b, out);
}

// ---------------------------------------------------------------- BIP39 + SLIP-10
// 16 bytes of entropy (as 4 big-endian u32) -> 12 word indices, with the BIP39 checksum
HD void entropy_words(const uint32_t ent[4], uint16_t idx[12]) {
  uint32_t cs = sha256_first_byte_16(ent) >> 4;  // 4 checksum bits
  // 132-bit stream: ent (128) || cs (4)
  for (int i = 0; i < 12; i++) {
    uint32_t v = 0;
    for (int b = 0; b < 11; b++) {
      int bit = i * 11 + b;
      uint32_t x = bit < 128 ? (ent[bit >> 5] >> (31 - (bit & 31))) & 1u : (cs >> (131 - bit)) & 1u;
      v = (v << 1) | x;
    }
    idx[i] = (uint16_t)v;
  }
}

// mnemonic sentence (words joined with spaces; at most 107 bytes) as a zero-padded 128-byte key block
HD void sentence_block(const uint16_t idx[12], uint64_t blk[16]) {
  for (int i = 0; i < 16; i++) blk[i] = 0;
  uint32_t L = 0;
  for (int w = 0; w < 12; w++) {
    if (w) { blk[L >> 3] |= (uint64_t)' ' << (56 - 8 * (L & 7)); L++; }
    const uint32_t o = WOFF[idx[w]], e = WOFF[idx[w] + 1];
    for (uint32_t j = o; j < e; j++) { blk[L >> 3] |= (uint64_t)(uint8_t)WCHARS[j] << (56 - 8 * (L & 7)); L++; }
  }
}

// BIP39 seed = PBKDF2-HMAC-SHA512(sentence, "mnemonic", 2048) -> 64 bytes
HD void bip39_seed(const uint16_t idx[12], uint64_t seed[8]) {
  uint64_t key[16];
  sentence_block(idx, key);
  HmacKey k;
  hmac_init(k, key);
  uint64_t b[16], u[8];
  b[0] = 0x6d6e656d6f6e6963ULL;  // "mnemonic"
  b[1] = 0x0000000180000000ULL;  // INT(1) || 0x80
  for (int i = 2; i < 15; i++) b[i] = 0;
  b[15] = (128 + 12) * 8;
  hmac_block(k, b, u);
  for (int i = 0; i < 8; i++) seed[i] = u[i];
  for (int j = 1; j < 2048; j++) {
    hmac64(k, u, u);
    for (int i = 0; i < 8; i++) seed[i] ^= u[i];
  }
}

// SLIP-10 ed25519, path m/44'/607'/0' -> 32-byte private key (Ed25519 seed)
HD void slip10_ton(const uint64_t seed[8], uint64_t priv[4]) {
  uint64_t key[16], I[8];
  for (int i = 0; i < 16; i++) key[i] = 0;
  key[0] = 0x6564323535313920ULL;  // "ed25519 "
  key[1] = 0x7365656400000000ULL;  // "seed"
  HmacKey k;
  hmac_init(k, key);
  hmac64(k, seed, I);  // master: kL = I[0..3], chain code = I[4..7]
  const uint32_t path[3] = {0x80000000u | 44u, 0x80000000u | 607u, 0x80000000u};
  for (int s = 0; s < 3; s++) {
    for (int i = 0; i < 16; i++) key[i] = 0;
    for (int i = 0; i < 4; i++) key[i] = I[4 + i];  // HMAC key = chain code
    hmac_init(k, key);
    uint64_t b[16];
    // data = 0x00 || kL (32 bytes) || index (4 bytes, big-endian), 37 bytes, then 0x80 padding
    b[0] = I[0] >> 8;
    b[1] = (I[0] << 56) | (I[1] >> 8);
    b[2] = (I[1] << 56) | (I[2] >> 8);
    b[3] = (I[2] << 56) | (I[3] >> 8);
    b[4] = (I[3] << 56) | ((uint64_t)path[s] << 24) | (0x80ULL << 16);
    for (int i = 5; i < 15; i++) b[i] = 0;
    b[15] = (128 + 37) * 8;
    hmac_block(k, b, I);
  }
  for (int i = 0; i < 4; i++) priv[i] = I[i];
}

// ---------------------------------------------------------------- ChaCha20 (random entropy)
#define QR(a, b, c, d) \
  a += b; d ^= a; d = (d << 16) | (d >> 16); c += d; b ^= c; b = (b << 12) | (b >> 20); \
  a += b; d ^= a; d = (d << 8) | (d >> 24);  c += d; b ^= c; b = (b << 7) | (b >> 25);

HD void chacha_entropy(const uint32_t key[8], uint64_t counter, uint32_t ent[4]) {
  uint32_t s[16] = {0x61707865u, 0x3320646eu, 0x79622d32u, 0x6b206574u,
                    key[0], key[1], key[2], key[3], key[4], key[5], key[6], key[7],
                    (uint32_t)counter, (uint32_t)(counter >> 32), 0x42495033u, 0x39616e63u};
  uint32_t x[16];
  for (int i = 0; i < 16; i++) x[i] = s[i];
  for (int r = 0; r < 10; r++) {
    QR(x[0], x[4], x[8], x[12]) QR(x[1], x[5], x[9], x[13]) QR(x[2], x[6], x[10], x[14]) QR(x[3], x[7], x[11], x[15])
    QR(x[0], x[5], x[10], x[15]) QR(x[1], x[6], x[11], x[12]) QR(x[2], x[7], x[8], x[13]) QR(x[3], x[4], x[9], x[14])
  }
  for (int i = 0; i < 4; i++) ent[i] = x[i] + s[i];
}

// entropy -> anchor private key (the whole GPU-side pipeline for one candidate)
HD void anchor_priv(const uint32_t ent[4], uint64_t priv[4]) {
  uint16_t idx[12];
  uint64_t seed[8];
  entropy_words(ent, idx);
  bip39_seed(idx, seed);
  slip10_ton(seed, priv);
}

// ---------------------------------------------------------------- Ed25519 public key (CPU and GPU)
// Field GF(2^255-19) in 5 limbs of 51 bits, 128-bit products (curve25519-donna-c64 layout).
typedef unsigned __int128 u128;
#define M51 0x7ffffffffffffULL
struct fe { uint64_t v[5]; };

HD void fe_carry(fe &r) {
  uint64_t c;
  c = r.v[0] >> 51; r.v[0] &= M51; r.v[1] += c;
  c = r.v[1] >> 51; r.v[1] &= M51; r.v[2] += c;
  c = r.v[2] >> 51; r.v[2] &= M51; r.v[3] += c;
  c = r.v[3] >> 51; r.v[3] &= M51; r.v[4] += c;
  c = r.v[4] >> 51; r.v[4] &= M51; r.v[0] += c * 19;
  c = r.v[0] >> 51; r.v[0] &= M51; r.v[1] += c;
}
HD fe fe_add(const fe &a, const fe &b) { fe r; for (int i = 0; i < 5; i++) r.v[i] = a.v[i] + b.v[i]; fe_carry(r); return r; }
// a - b + 4p, valid while limbs stay below 2^53 (they are carried after every operation)
HD fe fe_sub(const fe &a, const fe &b) {
  fe r;
  r.v[0] = a.v[0] + 0x1fffffffffffb4ULL - b.v[0];
  for (int i = 1; i < 5; i++) r.v[i] = a.v[i] + 0x1ffffffffffffcULL - b.v[i];
  fe_carry(r);
  return r;
}
HD fe fe_mul(const fe &a, const fe &b) {
  uint64_t b1 = b.v[1] * 19, b2 = b.v[2] * 19, b3 = b.v[3] * 19, b4 = b.v[4] * 19;
  u128 r0 = (u128)a.v[0] * b.v[0] + (u128)a.v[1] * b4 + (u128)a.v[2] * b3 + (u128)a.v[3] * b2 + (u128)a.v[4] * b1;
  u128 r1 = (u128)a.v[0] * b.v[1] + (u128)a.v[1] * b.v[0] + (u128)a.v[2] * b4 + (u128)a.v[3] * b3 + (u128)a.v[4] * b2;
  u128 r2 = (u128)a.v[0] * b.v[2] + (u128)a.v[1] * b.v[1] + (u128)a.v[2] * b.v[0] + (u128)a.v[3] * b4 + (u128)a.v[4] * b3;
  u128 r3 = (u128)a.v[0] * b.v[3] + (u128)a.v[1] * b.v[2] + (u128)a.v[2] * b.v[1] + (u128)a.v[3] * b.v[0] + (u128)a.v[4] * b4;
  u128 r4 = (u128)a.v[0] * b.v[4] + (u128)a.v[1] * b.v[3] + (u128)a.v[2] * b.v[2] + (u128)a.v[3] * b.v[1] + (u128)a.v[4] * b.v[0];
  fe r;
  r1 += (uint64_t)(r0 >> 51); r.v[0] = (uint64_t)r0 & M51;
  r2 += (uint64_t)(r1 >> 51); r.v[1] = (uint64_t)r1 & M51;
  r3 += (uint64_t)(r2 >> 51); r.v[2] = (uint64_t)r2 & M51;
  r4 += (uint64_t)(r3 >> 51); r.v[3] = (uint64_t)r3 & M51;
  uint64_t c = (uint64_t)(r4 >> 51); r.v[4] = (uint64_t)r4 & M51;
  r.v[0] += c * 19;
  c = r.v[0] >> 51; r.v[0] &= M51; r.v[1] += c;
  return r;
}
HD fe fe_sq(const fe &a) { return fe_mul(a, a); }
HD fe fe_sqn(fe a, int n) { for (int i = 0; i < n; i++) a = fe_sq(a); return a; }
// z^(p-2) (same addition chain as ref10)
HD fe fe_invert(const fe &z) {
  fe z2 = fe_sq(z);
  fe z9 = fe_mul(fe_sqn(z2, 2), z);
  fe z11 = fe_mul(z9, z2);
  fe z2_5 = fe_mul(fe_sq(z11), z9);
  fe z2_10 = fe_mul(fe_sqn(z2_5, 5), z2_5);
  fe z2_20 = fe_mul(fe_sqn(z2_10, 10), z2_10);
  fe z2_40 = fe_mul(fe_sqn(z2_20, 20), z2_20);
  fe z2_50 = fe_mul(fe_sqn(z2_40, 10), z2_10);
  fe z2_100 = fe_mul(fe_sqn(z2_50, 50), z2_50);
  fe z2_200 = fe_mul(fe_sqn(z2_100, 100), z2_100);
  fe z2_250 = fe_mul(fe_sqn(z2_200, 50), z2_50);
  return fe_mul(fe_sqn(z2_250, 5), z11);
}
// canonical little-endian encoding
HD void fe_tobytes(fe t, uint8_t out[32]) {
  fe_carry(t); fe_carry(t);
  fe u = t;
  u.v[0] += 19;
  uint64_t c;
  c = u.v[0] >> 51; u.v[0] &= M51; u.v[1] += c;
  c = u.v[1] >> 51; u.v[1] &= M51; u.v[2] += c;
  c = u.v[2] >> 51; u.v[2] &= M51; u.v[3] += c;
  c = u.v[3] >> 51; u.v[3] &= M51; u.v[4] += c;
  if (u.v[4] >> 51) { u.v[4] &= M51; t = u; }  // t >= p: use t - p
  uint64_t w0 = t.v[0] | (t.v[1] << 51), w1 = (t.v[1] >> 13) | (t.v[2] << 38);
  uint64_t w2 = (t.v[2] >> 26) | (t.v[3] << 25), w3 = (t.v[3] >> 39) | (t.v[4] << 12);
  const uint64_t w[4] = {w0, w1, w2, w3};
  for (int i = 0; i < 32; i++) out[i] = (uint8_t)(w[i >> 3] >> (8 * (i & 7)));
}

// Points: extended (X:Y:Z:T); precomputed table entries in "niels" form (y+x, y-x, 2dxy)
struct ge { fe X, Y, Z, T; };
struct gn { fe yp, ym, xy2d; };
// p + q (q affine, niels form); unified formulas for a = -1, valid for the identity too
HD ge ge_madd(const ge &p, const gn &q) {
  fe A = fe_mul(fe_sub(p.Y, p.X), q.ym);
  fe B = fe_mul(fe_add(p.Y, p.X), q.yp);
  fe C = fe_mul(p.T, q.xy2d);
  fe D = fe_add(p.Z, p.Z);
  fe E = fe_sub(B, A), F = fe_sub(D, C), G = fe_add(D, C), H = fe_add(B, A);
  ge r;
  r.X = fe_mul(E, F); r.Y = fe_mul(G, H); r.T = fe_mul(E, H); r.Z = fe_mul(F, G);
  return r;
}
HD gn ge_to_niels(const ge &p, const fe &d2) {
  fe zi = fe_invert(p.Z);
  fe x = fe_mul(p.X, zi), y = fe_mul(p.Y, zi);
  gn n;
  n.yp = fe_add(y, x); n.ym = fe_sub(y, x); n.xy2d = fe_mul(fe_mul(x, y), d2);
  return n;
}

// Table: TAB[i][j] = j * 16^i * B for i in 0..63, j in 0..15 (j = 0 is the identity)
#define ED_TAB_N (64 * 16)
static void build_ed_table(gn *tab) {
  const fe BX = {{0x62d608f25d51aULL,0x412a4b4f6592aULL,0x75b7171a4b31dULL,0x1ff60527118feULL,0x216936d3cd6e5ULL}}, BY = {{0x6666666666658ULL,0x4ccccccccccccULL,0x1999999999999ULL,0x3333333333333ULL,0x6666666666666ULL}}, D2 = {{0x69b9426b2f159ULL,0x35050762add7aULL,0x3cf44c0038052ULL,0x6738cc7407977ULL,0x2406d9dc56dffULL}};
  const fe one = {{1, 0, 0, 0, 0}}, zero = {{0, 0, 0, 0, 0}};
  ge base;  // 16^i * B, affine form refreshed each step
  base.X = BX; base.Y = BY; base.Z = one; base.T = fe_mul(BX, BY);
  for (int i = 0; i < 64; i++) {
    gn bn = ge_to_niels(base, D2);
    ge acc; acc.X = zero; acc.Y = one; acc.Z = one; acc.T = zero;  // identity
    for (int j = 0; j < 16; j++) {
      if (j == 0) { tab[i * 16].yp = one; tab[i * 16].ym = one; tab[i * 16].xy2d = zero; }
      else tab[i * 16 + j] = ge_to_niels(acc, D2);
      acc = ge_madd(acc, bn);
    }
    base = acc;  // 16 * (16^i * B)
  }
}

// Ed25519 public key from a 32-byte seed (as 4 big-endian words, the way the miner stores it)
HD void ed25519_pub_hd(const uint64_t seed[4], const gn *tab, uint8_t pub[32]) {
  uint64_t h[8], m[16];
  for (int i = 0; i < 4; i++) m[i] = seed[i];
  m[4] = 0x8000000000000000ULL;
  for (int i = 5; i < 15; i++) m[i] = 0;
  m[15] = 256;
  sha512_iv(h);
  sha512_compress(h, m);
  uint8_t s[32];
  for (int i = 0; i < 32; i++) s[i] = (uint8_t)(h[i >> 3] >> (56 - 8 * (i & 7)));
  s[0] &= 248; s[31] &= 127; s[31] |= 64;
  const fe one = {{1, 0, 0, 0, 0}}, zero = {{0, 0, 0, 0, 0}};
  ge acc; acc.X = zero; acc.Y = one; acc.Z = one; acc.T = zero;
  for (int i = 0; i < 64; i++) {
    int nib = (s[i >> 1] >> (4 * (i & 1))) & 15;
    acc = ge_madd(acc, tab[i * 16 + nib]);
  }
  fe zi = fe_invert(acc.Z);
  uint8_t xb[32];
  fe_tobytes(fe_mul(acc.X, zi), xb);
  fe_tobytes(fe_mul(acc.Y, zi), pub);
  pub[31] |= (xb[0] & 1) << 7;
}

// ---------------------------------------------------------------- WalletTg address (CPU and GPU)
HD void sha256_hd(const uint8_t *msg, uint32_t len, uint8_t out[32]) {  // len <= 119
  const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,
    0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,
    0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,
    0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};
  uint8_t buf[128];
  const uint32_t blocks = (len + 9 + 63) / 64;
  for (uint32_t i = 0; i < blocks * 64; i++) buf[i] = i < len ? msg[i] : 0;
  buf[len] = 0x80;
  const uint64_t bits = (uint64_t)len * 8;
  for (int i = 0; i < 8; i++) buf[blocks * 64 - 1 - i] = (uint8_t)(bits >> (8 * i));
  uint32_t H[8] = {0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19};
  for (uint32_t b = 0; b < blocks; b++) {
    uint32_t w[64];
    for (int i = 0; i < 16; i++) {
      const uint8_t *p = buf + b * 64 + i * 4;
      w[i] = ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3];
    }
    for (int i = 16; i < 64; i++) {
      uint32_t s0 = rotr32(w[i - 15], 7) ^ rotr32(w[i - 15], 18) ^ (w[i - 15] >> 3);
      uint32_t s1 = rotr32(w[i - 2], 17) ^ rotr32(w[i - 2], 19) ^ (w[i - 2] >> 10);
      w[i] = w[i - 16] + s0 + w[i - 7] + s1;
    }
    uint32_t a = H[0], c1 = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (int i = 0; i < 64; i++) {
      uint32_t t1 = h + (rotr32(e, 6) ^ rotr32(e, 11) ^ rotr32(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i];
      uint32_t t2 = (rotr32(a, 2) ^ rotr32(a, 13) ^ rotr32(a, 22)) + ((a & c1) ^ (a & c) ^ (c1 & c));
      h = g; g = f; f = e; e = d + t1; d = c; c = c1; c1 = a; a = t1 + t2;
    }
    H[0] += a; H[1] += c1; H[2] += c; H[3] += d; H[4] += e; H[5] += f; H[6] += g; H[7] += h;
  }
  for (int i = 0; i < 32; i++) out[i] = (uint8_t)(H[i >> 2] >> (24 - 8 * (i & 3)));
}

// friendly address (48 base64url chars, no terminator) of the WalletTg wallet for a public key
HD void wallet_address_hd(const uint8_t pub[32], bool bounceable, char out[48]) {
  const uint8_t TRAMP[32] = {
    0x91,0x49,0xae,0x51,0xc1,0xe4,0x68,0x97,0x10,0xce,0xbf,0x78,0x30,0x29,0x7b,0x16,
    0xac,0xfb,0xad,0xb3,0x63,0xa9,0x20,0xa5,0x37,0x89,0x3e,0x7f,0xfe,0xec,0xa7,0x68};
  uint8_t data[43] = {0, 82, 0, 0, 0, 0, 0, 0x7F, 0xFF, 0x7F, 0x11};
  for (int i = 0; i < 32; i++) data[11 + i] = pub[i];
  uint8_t si[71] = {2, 1, 0x34, 0, 0, 0, 0};
  for (int i = 0; i < 32; i++) si[7 + i] = TRAMP[i];
  sha256_hd(data, 43, si + 39);
  uint8_t raw[36];
  raw[0] = bounceable ? 0x11 : 0x51;
  raw[1] = 0;
  sha256_hd(si, 71, raw + 2);
  uint16_t crc = 0;
  for (int i = 0; i < 34; i++) {
    crc ^= (uint16_t)raw[i] << 8;
    for (int k = 0; k < 8; k++) crc = (crc & 0x8000) ? (uint16_t)((crc << 1) ^ 0x1021) : (uint16_t)(crc << 1);
  }
  raw[34] = crc >> 8; raw[35] = crc & 0xff;
  const char *abc = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
  for (int i = 0, o = 0; i < 36; i += 3) {
    uint32_t n = ((uint32_t)raw[i] << 16) | ((uint32_t)raw[i + 1] << 8) | raw[i + 2];
    out[o++] = abc[(n >> 18) & 63]; out[o++] = abc[(n >> 12) & 63]; out[o++] = abc[(n >> 6) & 63]; out[o++] = abc[n & 63];
  }
}

// pattern match on the GPU side (same rules as Pattern::match)
struct PatternHD { char suf[48], pre[48]; int sufLen, preLen; int icase; int bounce; };
HD char lowc(char c, int icase) { return (icase && c >= 'A' && c <= 'Z') ? (char)(c + 32) : c; }
HD bool match_hd(const char a[48], const PatternHD &p) {
  for (int i = 0; i < p.sufLen; i++) if (lowc(a[48 - p.sufLen + i], p.icase) != lowc(p.suf[i], p.icase)) return false;
  for (int i = 0; i < p.preLen; i++) if (lowc(a[3 + i], p.icase) != lowc(p.pre[i], p.icase)) return false;
  return true;
}

// ---------------------------------------------------------------- address (CPU)
static const uint8_t TRAMPOLINE_HASH[32] = {
  0x91,0x49,0xae,0x51,0xc1,0xe4,0x68,0x97,0x10,0xce,0xbf,0x78,0x30,0x29,0x7b,0x16,
  0xac,0xfb,0xad,0xb3,0x63,0xa9,0x20,0xa5,0x37,0x89,0x3e,0x7f,0xfe,0xec,0xa7,0x68};
static const uint32_t SUBWALLET_ID = 0x7FFF7F11u;

static void sha256(const uint8_t *data, size_t n, uint8_t out[32]) {
  unsigned int len = 32;
  EVP_Digest(data, n, out, &len, EVP_sha256(), nullptr);
}
static bool ed25519_pub(const uint8_t seed[32], uint8_t pub[32]) {
  EVP_PKEY *pk = EVP_PKEY_new_raw_private_key(EVP_PKEY_ED25519, nullptr, seed, 32);
  if (!pk) return false;
  size_t len = 32;
  bool ok = EVP_PKEY_get_raw_public_key(pk, pub, &len) == 1 && len == 32;
  EVP_PKEY_free(pk);
  return ok;
}
static uint16_t crc16(const uint8_t *d, size_t n) {
  uint16_t crc = 0;
  for (size_t i = 0; i < n; i++) {
    crc ^= (uint16_t)d[i] << 8;
    for (int k = 0; k < 8; k++) crc = (crc & 0x8000) ? (uint16_t)((crc << 1) ^ 0x1021) : (uint16_t)(crc << 1);
  }
  return crc;
}
// WalletTg address = hash(StateInit{ trampoline code, data: [rev 0, seqno 0, subwallet id, pubkey] })
static std::string wallet_address(const uint8_t pub[32], bool bounceable) {
  uint8_t data[43] = {0, 82, 0, 0, 0, 0, 0,
                      (uint8_t)(SUBWALLET_ID >> 24), (uint8_t)(SUBWALLET_ID >> 16), (uint8_t)(SUBWALLET_ID >> 8), (uint8_t)SUBWALLET_ID};
  memcpy(data + 11, pub, 32);
  uint8_t si[71] = {2, 1, 0x34, 0, 0, 0, 0};
  memcpy(si + 7, TRAMPOLINE_HASH, 32);
  sha256(data, 43, si + 39);
  uint8_t raw[36];
  raw[0] = bounceable ? 0x11 : 0x51;
  raw[1] = 0;
  sha256(si, 71, raw + 2);
  uint16_t c = crc16(raw, 34);
  raw[34] = c >> 8; raw[35] = c & 0xff;
  static const char *abc = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
  std::string s;
  for (int i = 0; i < 36; i += 3) {
    uint32_t n = (raw[i] << 16) | (raw[i + 1] << 8) | raw[i + 2];
    s += abc[(n >> 18) & 63]; s += abc[(n >> 12) & 63]; s += abc[(n >> 6) & 63]; s += abc[n & 63];
  }
  return s;
}
static void priv_bytes(const uint64_t p[4], uint8_t out[32]) {
  for (int i = 0; i < 4; i++)
    for (int j = 0; j < 8; j++) out[i * 8 + j] = (uint8_t)(p[i] >> (56 - 8 * j));
}
static std::string sentence(const uint16_t idx[12]) {
  std::string s;
  for (int w = 0; w < 12; w++) {
    if (w) s += ' ';
    s.append(h_words_chars + h_words_off[idx[w]], h_words_off[idx[w] + 1] - h_words_off[idx[w]]);
  }
  return s;
}
static bool parse_words(const std::string &phrase, std::vector<uint16_t> &idx) {
  idx.clear();
  size_t p = 0;
  while (p < phrase.size()) {
    while (p < phrase.size() && phrase[p] == ' ') p++;
    size_t q = p;
    while (q < phrase.size() && phrase[q] != ' ') q++;
    if (q > p) {
      std::string wd = phrase.substr(p, q - p);
      int found = -1;
      for (int k = 0; k < 2048 && found < 0; k++) {
        size_t len = h_words_off[k + 1] - h_words_off[k];
        if (len == wd.size() && memcmp(h_words_chars + h_words_off[k], wd.data(), len) == 0) found = k;
      }
      if (found < 0) return false;
      idx.push_back((uint16_t)found);
    }
    p = q;
  }
  return true;
}

// Independent derivation with OpenSSL (BIP39 PBKDF2 + SLIP-10 via HMAC); also checks the checksum.
static bool openssl_anchor(const uint16_t idx[12], uint8_t priv[32]) {
  // checksum: words -> 132 bits -> entropy (128) + checksum (4)
  uint8_t bits[17] = {0};
  for (int i = 0; i < 12; i++)
    for (int b = 0; b < 11; b++)
      if ((idx[i] >> (10 - b)) & 1) { int bit = i * 11 + b; bits[bit >> 3] |= 0x80 >> (bit & 7); }
  uint8_t h[32];
  sha256(bits, 16, h);
  if ((h[0] >> 4) != (bits[16] >> 4)) return false;
  std::string s = sentence(idx);
  uint8_t seed[64];
  if (PKCS5_PBKDF2_HMAC(s.data(), (int)s.size(), (const unsigned char *)"mnemonic", 8, 2048, EVP_sha512(), 64, seed) != 1) return false;
  uint8_t I[64];
  unsigned int len = 64;
  HMAC(EVP_sha512(), "ed25519 seed", 12, seed, 64, I, &len);
  const uint32_t path[3] = {0x80000000u | 44u, 0x80000000u | 607u, 0x80000000u};
  for (int k = 0; k < 3; k++) {
    uint8_t d[37];
    d[0] = 0;
    memcpy(d + 1, I, 32);
    d[33] = path[k] >> 24; d[34] = path[k] >> 16; d[35] = path[k] >> 8; d[36] = path[k];
    uint8_t chain[32];
    memcpy(chain, I + 32, 32);
    HMAC(EVP_sha512(), chain, 32, d, 37, I, &len);
  }
  memcpy(priv, I, 32);
  return true;
}
static std::string anchor_address_openssl(const uint16_t idx[12], bool bounceable) {
  uint8_t priv[32], pub[32];
  if (!openssl_anchor(idx, priv) || !ed25519_pub(priv, pub)) return "";
  return wallet_address(pub, bounceable);
}

// ---------------------------------------------------------------- pattern
struct Pattern {
  std::string suffix, prefix;
  bool icase = false, bounceable = false;
  static std::string low(std::string s) { for (auto &c : s) c = (char)tolower((unsigned char)c); return s; }
  bool match(const std::string &a0) const {
    std::string a = icase ? low(a0) : a0;
    std::string suf = icase ? low(suffix) : suffix, pre = icase ? low(prefix) : prefix;
    if (!suf.empty() && (a.size() < suf.size() || a.compare(a.size() - suf.size(), suf.size(), suf) != 0)) return false;
    if (!pre.empty() && a.compare(3, pre.size(), pre) != 0) return false;
    return true;
  }
  double expected() const {
    double n = 1;
    for (char ch : suffix + prefix) n *= (icase && isalpha((unsigned char)ch)) ? 32 : 64;
    return n;
  }
};
static bool valid_pattern(const std::string &s) {
  for (char c : s) if (!(isalnum((unsigned char)c) || c == '-' || c == '_')) return false;
  return true;
}

// ---------------------------------------------------------------- output
static std::mutex out_mu;
static std::atomic<int> found_count{0};
static std::string found_file = "found.txt";

static void report(const Pattern &pat, const uint32_t ent[4], const std::string &addr_fast) {
  uint16_t idx[12];
  entropy_words(ent, idx);
  std::string addr = anchor_address_openssl(idx, pat.bounceable);  // independent re-derivation
  std::lock_guard<std::mutex> g(out_mu);
  if (addr != addr_fast || !pat.match(addr)) {
    fprintf(stderr, "\n!! result failed the independent re-check (%s vs %s) — ignored. Report this.\n", addr_fast.c_str(), addr.c_str());
    return;
  }
  std::string words = sentence(idx);
  printf("\n\n=== FOUND ===\naddress:      %s\nanchor words: %s\n"
         "Next: on your own computer run  node finalize.mjs  and enter these 12 words.\n\n", addr.c_str(), words.c_str());
  fflush(stdout);
  if (FILE *f = fopen(found_file.c_str(), "a")) { fprintf(f, "%s %s\n", addr.c_str(), words.c_str()); fclose(f); }
  found_count++;
}

static std::string fmt_dur(double s) {
  if (!std::isfinite(s) || s > 3.15e9) return ">100y";
  char b[64];
  if (s >= 86400) snprintf(b, sizeof b, "%.0fd %.0fh", floor(s / 86400), fmod(s / 3600, 24));
  else if (s >= 3600) snprintf(b, sizeof b, "%.0fh %.0fm", floor(s / 3600), fmod(s / 60, 60));
  else snprintf(b, sizeof b, "%.0fm %02.0fs", floor(s / 60), fmod(s, 60));
  return b;
}
struct Progress {
  std::chrono::steady_clock::time_point t0 = std::chrono::steady_clock::now(), last;
  void tick(double total, double expected) {
    auto now = std::chrono::steady_clock::now();
    if (std::chrono::duration<double>(now - last).count() < 5) return;
    double el = std::chrono::duration<double>(now - t0).count();
    double rate = total / std::max(el, 1e-9);
    printf("\r[%s] %.0f addresses, %.0f/s, chance so far %.1f%%, expected left %s      ",
           fmt_dur(el).c_str(), total, rate, 100 * (1 - exp(-total / expected)),
           fmt_dur(std::max(0.0, expected - total) / std::max(rate, 1e-9)).c_str());
    fflush(stdout);
    last = now;
  }
};

// CPU stage: private key -> public key -> address -> match
static std::atomic<uint64_t> checked{0};
static void check_batch(const Pattern &pat, const uint32_t *ents, const uint64_t *privs, size_t n, int threads, int max_found) {
  std::vector<std::thread> ts;
  std::atomic<size_t> next{0};
  for (int t = 0; t < threads; t++) ts.emplace_back([&] {
    for (;;) {
      size_t i = next.fetch_add(1024);
      if (i >= n || found_count >= max_found) return;
      size_t e = std::min(n, i + 1024);
      for (; i < e; i++) {
        uint8_t sb[32], pub[32];
        priv_bytes(&privs[i * 4], sb);
        if (!ed25519_pub(sb, pub)) continue;
        std::string a = wallet_address(pub, pat.bounceable);
        if (pat.match(a)) report(pat, &ents[i * 4], a);
      }
      checked += 1024;
    }
  });
  for (auto &t : ts) t.join();
}

static void mine_cpu(const Pattern &pat, int threads, int max_found, const uint32_t key[8]) {
  std::atomic<uint64_t> counter{0};
  const size_t B = 4096;
  Progress pr;
  std::vector<uint32_t> ents(B * 4);
  std::vector<uint64_t> privs(B * 4);
  while (found_count < max_found) {
    std::vector<std::thread> ts;
    std::atomic<size_t> next{0};
    for (int t = 0; t < threads; t++) ts.emplace_back([&] {
      for (size_t i; (i = next.fetch_add(1)) < B;) {
        chacha_entropy(key, counter + i, &ents[i * 4]);
        anchor_priv(&ents[i * 4], &privs[i * 4]);
      }
    });
    for (auto &t : ts) t.join();
    counter += B;
    check_batch(pat, ents.data(), privs.data(), B, threads, max_found);
    pr.tick((double)checked, pat.expected());
  }
}

// ---------------------------------------------------------------- GPU
#ifdef __CUDACC__
__constant__ uint32_t d_key[8];

// One candidate per thread: entropy -> anchor private key. `fixed` = self-test entropies.
__global__ void k_mine(uint64_t base, uint32_t n, uint32_t *ents, uint64_t *privs, const uint32_t *fixed) {
  uint32_t tid = blockIdx.x * blockDim.x + threadIdx.x;
  if (tid >= n) return;
  uint32_t ent[4];
  if (fixed) { for (int i = 0; i < 4; i++) ent[i] = fixed[tid * 4 + i]; }
  else chacha_entropy(d_key, base + tid, ent);
  uint64_t priv[4];
  anchor_priv(ent, priv);
  for (int i = 0; i < 4; i++) { ents[tid * 4 + i] = ent[i]; privs[tid * 4 + i] = priv[i]; }
}

__constant__ PatternHD d_pat;

// Private key -> Ed25519 public key -> WalletTg address -> pattern; only matches leave the GPU
__global__ void k_addr(uint32_t n, const uint32_t *ents, const uint64_t *privs, const gn *tab, uint32_t *out, uint32_t *count, uint32_t cap) {
  uint32_t tid = blockIdx.x * blockDim.x + threadIdx.x;
  if (tid >= n) return;
  uint8_t pub[32];
  ed25519_pub_hd(&privs[tid * 4], tab, pub);
  char a[48];
  wallet_address_hd(pub, d_pat.bounce, a);
  if (!match_hd(a, d_pat)) return;
  uint32_t slot = atomicAdd(count, 1u);
  if (slot < cap) for (int i = 0; i < 4; i++) out[slot * 4 + i] = ents[tid * 4 + i];
}

// self-test helper: addresses for given private keys
__global__ void k_addr_test(uint32_t n, const uint64_t *privs, const gn *tab, char *out) {
  uint32_t tid = blockIdx.x * blockDim.x + threadIdx.x;
  if (tid >= n) return;
  uint8_t pub[32];
  ed25519_pub_hd(&privs[tid * 4], tab, pub);
  wallet_address_hd(pub, false, out + tid * 48);
}

#define CK(x) do { cudaError_t e_ = (x); if (e_ != cudaSuccess) { fprintf(stderr, "CUDA error %s at %s:%d\n", cudaGetErrorString(e_), __FILE__, __LINE__); exit(1); } } while (0)

static gn *d_tab = nullptr;
static void upload_ed_table() {
  if (d_tab) return;
  std::vector<gn> tab(ED_TAB_N);
  build_ed_table(tab.data());
  CK(cudaMalloc(&d_tab, sizeof(gn) * ED_TAB_N));
  CK(cudaMemcpy(d_tab, tab.data(), sizeof(gn) * ED_TAB_N, cudaMemcpyHostToDevice));
}

static bool gpu_selftest() {
  const int n = 64;
  std::vector<uint32_t> fixed(n * 4);
  for (int i = 0; i < n * 4; i++) fixed[i] = (uint32_t)(i * 2654435761u) ^ 0x5bd1e995u;
  uint32_t *d_fixed, *d_ents; uint64_t *d_privs;
  CK(cudaMalloc(&d_fixed, n * 16)); CK(cudaMalloc(&d_ents, n * 16)); CK(cudaMalloc(&d_privs, n * 32));
  CK(cudaMemcpy(d_fixed, fixed.data(), n * 16, cudaMemcpyHostToDevice));
  k_mine<<<1, 64>>>(0, n, d_ents, d_privs, d_fixed);
  CK(cudaGetLastError()); CK(cudaDeviceSynchronize());
  std::vector<uint64_t> privs(n * 4);
  CK(cudaMemcpy(privs.data(), d_privs, n * 32, cudaMemcpyDeviceToHost));
  cudaFree(d_fixed); cudaFree(d_ents); cudaFree(d_privs);
  for (int k = 0; k < n; k++) {
    uint16_t idx[12];
    entropy_words(&fixed[k * 4], idx);
    uint8_t ref[32], got[32];
    if (!openssl_anchor(idx, ref)) { fprintf(stderr, "GPU self-test: checksum error\n"); return false; }
    priv_bytes(&privs[k * 4], got);
    if (memcmp(ref, got, 32) != 0) { fprintf(stderr, "GPU self-test: key mismatch at %d\n", k); return false; }
  }
  // Ed25519 + address on the GPU vs OpenSSL on the CPU
  upload_ed_table();
  uint64_t *d_p; char *d_out;
  CK(cudaMalloc(&d_p, n * 32)); CK(cudaMalloc(&d_out, n * 48));
  CK(cudaMemcpy(d_p, privs.data(), n * 32, cudaMemcpyHostToDevice));
  k_addr_test<<<1, 64>>>(n, d_p, d_tab, d_out);
  CK(cudaGetLastError()); CK(cudaDeviceSynchronize());
  std::vector<char> addrs(n * 48);
  CK(cudaMemcpy(addrs.data(), d_out, n * 48, cudaMemcpyDeviceToHost));
  cudaFree(d_p); cudaFree(d_out);
  for (int k = 0; k < n; k++) {
    uint8_t sb[32], pub[32];
    priv_bytes(&privs[k * 4], sb);
    if (!ed25519_pub(sb, pub) || wallet_address(pub, false) != std::string(&addrs[k * 48], 48)) {
      fprintf(stderr, "GPU self-test: address mismatch at %d\n", k);
      return false;
    }
  }
  return true;
}

static void mine_gpu(const Pattern &pat, int threads, int max_found, const uint32_t key[8], uint32_t batch) {
  (void)threads;
  CK(cudaMemcpyToSymbol(d_key, key, 32));
  PatternHD ph = {};
  ph.sufLen = (int)pat.suffix.size(); ph.preLen = (int)pat.prefix.size();
  memcpy(ph.suf, pat.suffix.data(), ph.sufLen); memcpy(ph.pre, pat.prefix.data(), ph.preLen);
  ph.icase = pat.icase; ph.bounce = pat.bounceable;
  CK(cudaMemcpyToSymbol(d_pat, &ph, sizeof ph));
  upload_ed_table();
  const uint32_t cap = 1024;
  uint32_t *d_ents, *d_out, *d_cnt; uint64_t *d_privs;
  CK(cudaMalloc(&d_ents, (size_t)batch * 16)); CK(cudaMalloc(&d_privs, (size_t)batch * 32));
  CK(cudaMalloc(&d_out, cap * 16)); CK(cudaMalloc(&d_cnt, 4));
  CK(cudaMemset(d_cnt, 0, 4));
  std::vector<uint32_t> out(cap * 4);
  uint64_t counter = 0;
  Progress pr;
  while (found_count < max_found) {
    // everything for a batch runs on the GPU; the CPU only sees matches
    k_mine<<<(batch + 127) / 128, 128>>>(counter, batch, d_ents, d_privs, nullptr);
    k_addr<<<(batch + 127) / 128, 128>>>(batch, d_ents, d_privs, d_tab, d_out, d_cnt, cap);
    counter += batch;
    CK(cudaGetLastError()); CK(cudaDeviceSynchronize());
    uint32_t cnt = 0;
    CK(cudaMemcpy(&cnt, d_cnt, 4, cudaMemcpyDeviceToHost));
    if (cnt) {
      cnt = std::min(cnt, cap);
      CK(cudaMemcpy(out.data(), d_out, (size_t)cnt * 16, cudaMemcpyDeviceToHost));
      CK(cudaMemset(d_cnt, 0, 4));
      for (uint32_t i = 0; i < cnt && found_count < max_found; i++) {
        // CPU address with OpenSSL for the comparison inside report()
        uint64_t pk[4]; uint8_t sb[32], pub[32];
        anchor_priv(&out[i * 4], pk);
        priv_bytes(pk, sb);
        if (!ed25519_pub(sb, pub)) continue;
        report(pat, &out[i * 4], wallet_address(pub, pat.bounceable));
      }
    }
    checked += batch;
    pr.tick((double)checked, pat.expected());
  }
  cudaFree(d_ents); cudaFree(d_privs); cudaFree(d_out); cudaFree(d_cnt);
}
#endif

// ---------------------------------------------------------------- main
static void usage() {
  printf(
    "tgvanity — vanity addresses for Telegram Gram Wallet (12 + 12 words format)\n\n"
    "  tgvanity --suffix TON [--prefix ABC] [--icase] [--count 1] [--threads N]\n"
    "  tgvanity --derive \"12 anchor words\"     print the WalletTg address of an anchor phrase\n"
    "  tgvanity --selftest\n\n"
    "Options:\n"
    "  --suffix S     end of the address (letters, digits, - and _)\n"
    "  --prefix S     start of the address right after \"UQ\" + one character\n"
    "  --icase        ignore letter case\n"
    "  --eq           match the bounceable EQ... form instead of UQ...\n"
    "  --count N      stop after N matches (default 1)\n"
    "  --threads N    CPU threads (default: all cores)\n"
    "  --cpu          do not use the GPU\n"
    "  --batch N      candidates per GPU launch (default 1048576)\n"
    "  --out FILE     where matches are appended (default found.txt)\n\n"
    "A match gives the 12 ANCHOR words. Finish on your own computer with finalize.mjs: it creates the\n"
    "other 12 words, deploys the wallet and switches it to them; then import all 24 in Gram Wallet.\n");
}

int main(int argc, char **argv) {
  Pattern pat;
  int count = 1, threads = (int)std::max(1u, std::thread::hardware_concurrency());
  bool cpu_only = false, selftest_only = false;
  uint32_t batch = 1u << 20;
  std::string derive;
  for (int i = 1; i < argc; i++) {
    std::string a = argv[i];
    auto next = [&]() -> std::string { if (i + 1 >= argc) { fprintf(stderr, "%s needs a value\n", a.c_str()); exit(2); } return argv[++i]; };
    if (a == "--suffix") pat.suffix = next();
    else if (a == "--prefix") pat.prefix = next();
    else if (a == "--icase") pat.icase = true;
    else if (a == "--eq") pat.bounceable = true;
    else if (a == "--count") count = atoi(next().c_str());
    else if (a == "--threads") threads = atoi(next().c_str());
    else if (a == "--cpu") cpu_only = true;
    else if (a == "--batch") batch = (uint32_t)atol(next().c_str());
    else if (a == "--out") found_file = next();
    else if (a == "--derive") derive = next();
    else if (a == "--selftest") selftest_only = true;
    else { usage(); return a == "-h" || a == "--help" ? 0 : 2; }
  }

  if (!derive.empty()) {
    std::vector<uint16_t> idx;
    if (!parse_words(derive, idx) || idx.size() != 12) { fprintf(stderr, "need 12 words from the BIP-39 English list\n"); return 2; }
    std::string a = anchor_address_openssl(idx.data(), pat.bounceable);
    if (a.empty()) { fprintf(stderr, "invalid BIP-39 checksum: a word is wrong or out of order\n"); return 1; }
    printf("%s\n", a.c_str());
    return 0;
  }

  // ---- self-test: known phrase -> known address (matches MyTonWallet's derivation),
  //      and the GPU/CPU pipeline must equal the independent OpenSSL derivation
  {
    std::vector<uint16_t> idx;
    parse_words("abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about", idx);
    std::string a = anchor_address_openssl(idx.data(), false);
    uint32_t ent[4] = {0, 0, 0, 0};  // "abandon x11 about" is all-zero entropy
    uint64_t priv[4];
    anchor_priv(ent, priv);
    uint8_t pb[32], pub[32];
    priv_bytes(priv, pb);
    bool ok = a == "UQD4d2pzr-W4jzh1wOd52HrsH7rRagzkSUPC3_jCgMxmKz_L" && ed25519_pub(pb, pub) && wallet_address(pub, false) == a;
    if (!ok) { fprintf(stderr, "CPU self-test FAILED (%s). Do not use this build.\n", a.c_str()); return 1; }
    // Ed25519 + address code used on the GPU, checked here on the CPU against OpenSSL
    std::vector<gn> tab(ED_TAB_N);
    build_ed_table(tab.data());
    uint32_t tk[8];
    RAND_bytes((unsigned char *)tk, sizeof tk);
    for (int k = 0; k < 300; k++) {
      uint32_t e[4]; uint64_t pk[4]; uint8_t sb[32], ref[32], got[32]; char addr[48];
      chacha_entropy(tk, k, e);
      for (int i = 0; i < 4; i++) pk[i] = ((uint64_t)e[i] << 32) ^ ((uint64_t)e[(i + 1) & 3] * 0x9e3779b97f4a7c15ULL);
      priv_bytes(pk, sb);
      ed25519_pub_hd(pk, tab.data(), got);
      wallet_address_hd(got, false, addr);
      if (!ed25519_pub(sb, ref) || memcmp(ref, got, 32) != 0 || wallet_address(ref, false) != std::string(addr, 48)) {
        fprintf(stderr, "CPU self-test FAILED: Ed25519/address mismatch at %d. Do not use this build.\n", k);
        return 1;
      }
    }
    printf("CPU self-test: ok\n");
  }
  bool have_gpu = false;
#ifdef __CUDACC__
  int ndev = 0;
  have_gpu = !cpu_only && cudaGetDeviceCount(&ndev) == cudaSuccess && ndev > 0;
  if (have_gpu) {
    cudaDeviceProp prop;
    CK(cudaGetDeviceProperties(&prop, 0));
    printf("GPU: %s, %d SMs\n", prop.name, prop.multiProcessorCount);
    if (!gpu_selftest()) { fprintf(stderr, "GPU self-test FAILED. Do not use the GPU path (--cpu works).\n"); return 1; }
    printf("GPU self-test: ok\n");
  } else if (!cpu_only) {
    printf("No CUDA GPU found, using CPU only.\n");
  }
#endif
  if (selftest_only) return 0;
  if (pat.suffix.empty() && pat.prefix.empty()) { usage(); return 2; }
  if (!valid_pattern(pat.suffix) || !valid_pattern(pat.prefix)) { fprintf(stderr, "pattern may contain only A-Z a-z 0-9 - _\n"); return 2; }

  uint32_t key[8];
  if (RAND_bytes((unsigned char *)key, sizeof key) != 1) { fprintf(stderr, "no secure randomness\n"); return 1; }
  printf("Pattern: %s...%s%s (%s), expected attempts: %.0f, CPU threads: %d\n", pat.prefix.c_str(), pat.suffix.c_str(),
         pat.icase ? " ignoring case" : "", pat.bounceable ? "EQ" : "UQ", pat.expected(), threads);
  printf("Matches are appended to %s\n", found_file.c_str());
  fflush(stdout);
#ifdef __CUDACC__
  if (have_gpu) mine_gpu(pat, threads, count, key, batch);
  else
#endif
    mine_cpu(pat, threads, count, key);
  (void)have_gpu; (void)batch;
  printf("\nDone.\n");
  return 0;
}
